export function QuoteRequestForm({
  heading = "{{heading}}",
  serviceType = "{{serviceType}}",
  submitText = "{{submitText}}",
  accent = "{{accent}}",
}) {
  return (
    <form style={{ font: "15px system-ui, sans-serif", color: "#241430", display: "flex", flexDirection: "column",
      gap: 8, maxWidth: 320, padding: 22, border: "1px solid #24143022", borderRadius: 14, background: "#FAF7F2" }}>
      <h2 style={{ margin: "0 0 8px", fontSize: 19, fontWeight: 700 }}>{heading}</h2>
      <label htmlFor="quote-service" style={{ fontSize: 13, fontWeight: 600 }}>Service type</label>
      <select id="quote-service" name="service" defaultValue={serviceType}
        style={{ font: "inherit", padding: "9px 11px", border: "1px solid #24143033", borderRadius: 8, background: "#FAF7F2" }}>
        <option>Web</option>
        <option>Branding</option>
        <option>Marketing</option>
      </select>
      <label htmlFor="quote-budget" style={{ fontSize: 13, fontWeight: 600 }}>Budget range</label>
      <input id="quote-budget" type="text" name="budget" placeholder="$5,000 - $10,000"
        style={{ font: "inherit", padding: "9px 11px", border: "1px solid #24143033", borderRadius: 8 }} />
      <label htmlFor="quote-details" style={{ fontSize: 13, fontWeight: 600 }}>Project details</label>
      <textarea id="quote-details" name="details" rows={3}
        style={{ font: "inherit", padding: "9px 11px", border: "1px solid #24143033", borderRadius: 8 }} />
      <button type="submit" style={{ marginTop: 10, border: "none", color: "#241430", padding: 11, borderRadius: 8,
        fontWeight: 700, cursor: "pointer", background: accent }}>{submitText}</button>
    </form>
  );
}
